Definition re_ivs : list (Z * Z) :=
  [(0x10000,0x127ec0); (0x127ec1,0x127f09); (0x137f09,0x138100); (0x1381e8,0x1581f8); (0x138134,0x138180); (0x138188,0x1381a0);
